                json.dump(payload, handle, ensure_ascii=False, separators=(",", ":"))
                handle.write("\n")
            os.replace(tmp_name, path)
        except BaseException:
            # 出错时清理临时文件，避免残留。
            try:
                os.unlink(tmp_name)
            except FileNotFoundError:
                pass
            raise

